import Foundation

struct Pair: Hashable { let name: String; let url: String }
func check(_ value: Bool, _ message: String) { if !value { fputs("FAIL: \(message)\n", stderr); exit(1) } }
func pairs(from source: String) -> [Pair] {
    let pattern = #"name:\s*"([^\"]+)"[\s\S]{0,700}?string:\s*"([^\"]+)""#
    let regex = try! NSRegularExpression(pattern: pattern)
    return regex.matches(in: source, range: NSRange(source.startIndex..., in: source)).compactMap {
        guard let n = Range($0.range(at: 1), in: source), let u = Range($0.range(at: 2), in: source) else { return nil }
        return Pair(name: String(source[n]), url: String(source[u]))
    }
}
func legacySource() -> String? {
