    process.executableURL = URL(fileURLWithPath: "/usr/bin/git")
    process.arguments = ["show", "2.2.0:wBlock/FilterListLoader.swift"]
    process.standardOutput = pipe; process.standardError = Pipe()
    do { try process.run(); process.waitUntilExit(); guard process.terminationStatus == 0 else { return nil }; return String(data: pipe.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) } catch { return nil }
}
